272	template <typename Element_, typename Shape_, typename Stride_, Layout Layout_ = Layout::ND>
273	struct GlobalTensor {
274	    using Shape = Shape_;
275	    using Stride = Stride_;
276	    using RawDType = remove_gm_t<Element_>;
277	    using DType = __gm__ RawDType;
278	    static constexpr Layout layout = Layout_;
279	
280	    static const Shape defaultShape;
281	    static const Stride defaultStride;
282	
283	    static constexpr int64_t staticShape[GlobalTensorDim::TOTAL_DIM] = {
284	        Shape::staticShape[GlobalTensorDim::DIM_0], Shape::staticShape[GlobalTensorDim::DIM_1],
285	        Shape::staticShape[GlobalTensorDim::DIM_2], Shape::staticShape[GlobalTensorDim::DIM_3],
286	        Shape::staticShape[GlobalTensorDim::DIM_4]};
287	    static constexpr int64_t staticStride[GlobalTensorDim::TOTAL_DIM] = {
288	        Stride::staticStride[GlobalTensorDim::DIM_0], Stride::staticStride[GlobalTensorDim::DIM_1],
289	        Stride::staticStride[GlobalTensorDim::DIM_2], Stride::staticStride[GlobalTensorDim::DIM_3],
290	        Stride::staticStride[GlobalTensorDim::DIM_4]};
291	    PTO_INTERNAL GlobalTensor(DType* data, const Shape& shape = defaultShape, const Stride& stride = defaultStride)
292	    {
293	        data_ = data;
294	
295	        if constexpr (staticShape[GlobalTensorDim::DIM_0] == DYNAMIC) {
296	            shape_.shape[GlobalTensorDim::DIM_0] = shape.shape[GlobalTensorDim::DIM_0];
297	        }
298	        if constexpr (staticShape[GlobalTensorDim::DIM_1] == DYNAMIC) {
299	            shape_.shape[GlobalTensorDim::DIM_1] = shape.shape[GlobalTensorDim::DIM_1];
300	        }
301	        if constexpr (staticShape[GlobalTensorDim::DIM_2] == DYNAMIC) {
302	            shape_.shape[GlobalTensorDim::DIM_2] = shape.shape[GlobalTensorDim::DIM_2];
303	        }
304	        if constexpr (staticShape[GlobalTensorDim::DIM_3] == DYNAMIC) {
305	            shape_.shape[GlobalTensorDim::DIM_3] = shape.shape[GlobalTensorDim::DIM_3];
306	        }
307	        if constexpr (staticShape[GlobalTensorDim::DIM_4] == DYNAMIC) {
308	            shape_.shape[GlobalTensorDim::DIM_4] = shape.shape[GlobalTensorDim::DIM_4];
309	        }
310	
311	        if constexpr (staticStride[GlobalTensorDim::DIM_0] == DYNAMIC) {
312	            stride_.stride[GlobalTensorDim::DIM_0] = stride.stride[GlobalTensorDim::DIM_0];
313	        }
314	        if constexpr (staticStride[GlobalTensorDim::DIM_1] == DYNAMIC) {
315	            stride_.stride[GlobalTensorDim::DIM_1] = stride.stride[GlobalTensorDim::DIM_1];
316	        }
317	        if constexpr (staticStride[GlobalTensorDim::DIM_2] == DYNAMIC) {
318	            stride_.stride[GlobalTensorDim::DIM_2] = stride.stride[GlobalTensorDim::DIM_2];
319	        }
320	        if constexpr (staticStride[GlobalTensorDim::DIM_3] == DYNAMIC) {
321	            stride_.stride[GlobalTensorDim::DIM_3] = stride.stride[GlobalTensorDim::DIM_3];
322	        }
323	        if constexpr (staticStride[GlobalTensorDim::DIM_4] == DYNAMIC) {
324	            stride_.stride[GlobalTensorDim::DIM_4] = stride.stride[GlobalTensorDim::DIM_4];
325	        }
326	    }
327	    PTO_INTERNAL GlobalTensor() : data_(nullptr) {}
