329	    PTO_INTERNAL int64_t GetShape(const int dim)
330	    {
331	        switch (dim) {
332	            case GlobalTensorDim::DIM_0:
333	                return GetShapeSize<staticShape[GlobalTensorDim::DIM_0]>(dim);
334	            case GlobalTensorDim::DIM_1:
335	                return GetShapeSize<staticShape[GlobalTensorDim::DIM_1]>(dim);
336	            case GlobalTensorDim::DIM_2:
337	                return GetShapeSize<staticShape[GlobalTensorDim::DIM_2]>(dim);
338	            case GlobalTensorDim::DIM_3:
339	                return GetShapeSize<staticShape[GlobalTensorDim::DIM_3]>(dim);
340	            case GlobalTensorDim::DIM_4:
341	                return GetShapeSize<staticShape[GlobalTensorDim::DIM_4]>(dim);
342	            default:
343	                return -1;
344	        }
345	    }
