441	    {
442	        static_assert(dim >= GlobalTensorDim::DIM_0 && dim < GlobalTensorDim::TOTAL_DIM, "only support set dim(0-4)");
443	        static_assert(staticShape[dim] == DYNAMIC, "dim must be DYNAMIC");
