1091	template <int N, int64_t... Shapes>
1092	struct GetNthShape {
1093	    static constexpr int64_t value = []() {
1094	        int idx = 0;
1095	        int64_t val = 0;
1096	        ((idx == N ? (val = Shapes, idx++) : idx++), ...);
1097	        return val;
1098	    }();
1099	};
1100	
1101	template <int64_t... Shapes>
1102	struct CountDynamicDim {
1103	    static constexpr int value = []() {
1104	        int count = 0;
1105	        count += (GetNthShape<0, Shapes...>::value == DYNAMIC ? 1 : 0);
1106	        count += (GetNthShape<1, Shapes...>::value == DYNAMIC ? 1 : 0);
1107	        count += (GetNthShape<2, Shapes...>::value == DYNAMIC ? 1 : 0);
1108	        count += (GetNthShape<3, Shapes...>::value == DYNAMIC ? 1 : 0);
1109	        count += (GetNthShape<4, Shapes...>::value == DYNAMIC ? 1 : 0);
1110	        count += (GetNthShape<5, Shapes...>::value == DYNAMIC ? 1 : 0);
1111	        return count;
1112	    }();
1113	};
1114	
1115	template <int DimIdx, int64_t... Shapes>
1116	struct AssignDynamicDim {
1117	    static void apply(int64_t* shape, const int* vals, int& val_idx)
1118	    {
1119	        if constexpr (GetNthShape<DimIdx, Shapes...>::value == DYNAMIC) {
1120	            shape[DimIdx] = vals[val_idx++];
1121	        }
1122	        if constexpr (DimIdx + 1 < static_cast<int>(MAX_CONVTILE_DIM)) {
1123	            AssignDynamicDim<DimIdx + 1, Shapes...>::apply(shape, vals, val_idx);
1124	        }
1125	    }
1126	};
