1786	struct is_global<GlobalTensor<Element_, Shape_, Stride_, Layout_>> : std::true_type {};
1787	
1788	template <
1789	    TileType Loc_, typename Element_, const int Rows_, const int Cols_, const BLayout BFractal_, const int RowValid_,
1790	    const int ColValid_, const SLayout SFractal_, const int SFractalSize_, const PadValue PadVal_,
1791	    const CompactMode Compact_>
1792	struct is_tile<
1793	    Tile<Loc_, Element_, Rows_, Cols_, BFractal_, RowValid_, ColValid_, SFractal_, SFractalSize_, PadVal_, Compact_>>
1794	    : std::true_type {
1795	    static constexpr SLayout layout_enum = SFractal_;
1796	};
1797	
1798	template <typename T>
1799	constexpr bool is_boxed_tile = is_tile<T>::value && (is_tile<T>::layout_enum != SLayout::NoneBox);
1800	
1801	template <typename T>
1802	struct is_conv_tile : std::false_type {};
1803	template <TileType Loc_, typename Element_, const int BufferSize_, Layout Layout_, typename Shape_>
1804	struct is_conv_tile<ConvTile<Loc_, Element_, BufferSize_, Layout_, Shape_>> : std::true_type {};
1805	
1806	template <typename tile_shape>
1807	struct is_Nz_layout {
1808	    static constexpr bool value = !tile_shape::isRowMajor && tile_shape::isBoxedLayout && tile_shape::isInnerRowMajor;
1809	};
1810	
1811	template <typename tile_shape>
1812	struct is_Zn_layout {
1813	    static constexpr bool value = tile_shape::isRowMajor && tile_shape::isBoxedLayout && tile_shape::isInnerColMajor;
1814	};
1815	
1816	template <typename tile_shape>
1817	struct is_Zz_layout {
1818	    static constexpr bool value = tile_shape::isRowMajor && tile_shape::isBoxedLayout && tile_shape::isInnerRowMajor;
1819	};
1820	template <typename T>
1821	constexpr bool is_conv_tile_v = is_conv_tile<T>::value;
1822	
1823	template <typename T>
1824	constexpr bool is_global_data_v = is_global<T>::value;
1825	
1826	template <typename T>
1827	constexpr bool is_tile_data_v = is_tile<T>::value;
1828	
1829	template <typename T>
1830	constexpr bool is_boxed_data_v = is_boxed_tile<T>;
1831	
1832	// Maps logical tile coordinates to the backing storage offset.
1833	template <typename TileT>
1834	PTO_INTERNAL size_t GetTileOffset(int row, int col)
1835	{
1836	    static_assert(is_tile_data_v<TileT>, "tile_offset only accepts Tile types.");
1837	    if constexpr (!TileT::isBoxedLayout) {
1838	        return row * TileT::RowStride + col * TileT::ColStride;
1839	    } else {
1840	        int BlockRow = row / TileT::InnerRows;
1841	        int BlockCol = col / TileT::InnerCols;
1842	        int InnerRow = row % TileT::InnerRows;
1843	        int InnerCol = col % TileT::InnerCols;
1844	        static constexpr int BlockNumRow = TileT::Rows / TileT::InnerRows;
1845	        static constexpr int BlockNumCol = TileT::Cols / TileT::InnerCols;
1846	        if constexpr (is_Nz_layout<TileT>::value) {
1847	            return (BlockNumRow * BlockCol + BlockRow) * TileT::InnerNumel + InnerRow * TileT::InnerCols + InnerCol;
1848	        } else if constexpr (is_Zn_layout<TileT>::value) {
1849	            return (BlockNumCol * BlockRow + BlockCol) * TileT::InnerNumel + InnerCol * TileT::InnerRows + InnerRow;
1850	        } else if constexpr (is_Zz_layout<TileT>::value) {
1851	            return (BlockNumCol * BlockRow + BlockCol) * TileT::InnerNumel + InnerRow * TileT::InnerCols + InnerCol;
1852	        } else {
1853	            static_assert(
1854	                sizeof(TileT) == 0, "Unsupported layout in Tile, fractal tiles should be "
1855	                                    "Nz or Zn layout.");
1856	        }
1857	    }
1858	}
1859	
1860	} // namespace pto
1861	
1862	#endif
