        case TileType::Bias:
            return "Bias";
        case TileType::Scaling:
            return "Scaling";
        case TileType::ScaleLeft:
            return "ScaleLeft";
        case TileType::ScaleRight:
            return "ScaleRight";
        case TileType::Ctrl:
            return "Ctrl";
        default:
            return "Unknown";
    }
}

