22	template <typename GlobalData, typename TileData>
23	PTO_INLINE void CheckTileDataStore(GlobalData& dst, TileData& src)
24	{
25	    constexpr size_t C0 = GetC0ElemCount<typename GlobalData::DType>();
26	    if constexpr (GlobalData::layout == pto::Layout::NZ) {
27	        assert(
28	            src.GetValidRow() == dst.GetShape(GlobalTensorDim::DIM_2) * dst.GetShape(GlobalTensorDim::DIM_3) &&
29	            src.GetValidCol() == dst.GetShape(GlobalTensorDim::DIM_0) * dst.GetShape(GlobalTensorDim::DIM_1) *
30	                                     dst.GetShape(GlobalTensorDim::DIM_4));
31	
32	    } else {
33	        assert(
34	            dst.GetShape(GlobalTensorDim::DIM_0) * dst.GetShape(GlobalTensorDim::DIM_1) *
35	                dst.GetShape(GlobalTensorDim::DIM_2) * dst.GetShape(GlobalTensorDim::DIM_3) *
36	                dst.GetShape(GlobalTensorDim::DIM_4) * C0 >=
37	            src.GetValidRow() * src.GetValidCol());
38	    }
39	}
40	
41	template <
42	    typename GlobalData, typename TileData, QuantMode_t quantMode, bool applyRelu,
43	    AtomicType atomicType = AtomicType::AtomicNone>
44	__tf__ PTO_INLINE void TStore(GlobalData& dst, TileData& src, const std::vector<uint64_t>& scalars)
45	{
46	    using DT = typename GlobalData::DType;
47	    using ST = typename TileData::DType;
48	
49	    CheckTileDataStore(dst, src);
50	
51	    const size_t validRow = src.GetValidRow();
52	    const size_t validCol = src.GetValidCol();
53	
54	    const std::vector<int64_t> shapes = {
55	        dst.GetShape(GlobalTensorDim::DIM_0), dst.GetShape(GlobalTensorDim::DIM_1),
56	        dst.GetShape(GlobalTensorDim::DIM_2), dst.GetShape(GlobalTensorDim::DIM_3),
57	        dst.GetShape(GlobalTensorDim::DIM_4)};
58	    const std::vector<int64_t> strides = {
59	        dst.GetStride(GlobalTensorDim::DIM_0), dst.GetStride(GlobalTensorDim::DIM_1),
60	        dst.GetStride(GlobalTensorDim::DIM_2), dst.GetStride(GlobalTensorDim::DIM_3),
61	        dst.GetStride(GlobalTensorDim::DIM_4)};
62	
63	    uint64_t scalar = 0;
64	    for (size_t row = 0; row < validRow; ++row) {
65	        for (size_t col = 0; col < validCol; ++col) {
66	            if constexpr (quantMode != QuantMode_t::NoQuant) {
67	                scalar = scalars[TileData::isRowMajor ? col : row];
68	            }
69	            ST val = src.GetElement(row, col);
70	            DT dstVal = ConvertStoreValue<DT, ST, quantMode, applyRelu>(val, scalar);
71	            const size_t dstOffset = MapTileIndicesToGlobalOffset<GlobalData>(row, col, shapes, strides);
72	            if constexpr (atomicType == AtomicType::AtomicAdd) {
73	                dst.AddToElement(dstOffset, dstVal);
74	            } else {
75	                dst.SetElement(dstOffset, dstVal);
76	            }
77	        }
78	    }
79	}
80	
81	template <typename GlobalData, typename ConTile, AtomicType atomicType = AtomicType::AtomicNone>
82	__tf__ PTO_INLINE void TStoreConv(GlobalData& dst, ConTile& src)
83	{
84	    using T = typename ConTile::DType;
85	    CheckConvTileData<ConTile, GlobalData>(src, dst);
86	
87	    const size_t validRow = CalculateValidRowFromTile(src);
88	    const size_t validCol = CalculateValidColFromTile(src);
89	
90	    const std::vector<int64_t> tile_shapes = {
91	        src.GetShape(GlobalTensorDim::DIM_0), src.GetShape(GlobalTensorDim::DIM_1),
92	        src.GetShape(GlobalTensorDim::DIM_2), src.GetShape(GlobalTensorDim::DIM_3),
93	        src.GetShape(GlobalTensorDim::DIM_4)};
94	
95	    const std::vector<int64_t> shapes = {
96	        dst.GetShape(GlobalTensorDim::DIM_0), dst.GetShape(GlobalTensorDim::DIM_1),
97	        dst.GetShape(GlobalTensorDim::DIM_2), dst.GetShape(GlobalTensorDim::DIM_3),
98	        dst.GetShape(GlobalTensorDim::DIM_4)};
99	    const std::vector<int64_t> strides = {
100	        dst.GetStride(GlobalTensorDim::DIM_0), dst.GetStride(GlobalTensorDim::DIM_1),
101	        dst.GetStride(GlobalTensorDim::DIM_2), dst.GetStride(GlobalTensorDim::DIM_3),
102	        dst.GetStride(GlobalTensorDim::DIM_4)};
103	
104	    uint64_t scalar = 0;
105	    for (size_t row = 0; row < validRow; ++row) {
106	        for (size_t col = 0; col < validCol; ++col) {
107	            T val = src.data()[GetConvTileElementOffset<ConTile>(row, col, tile_shapes)];
108	            const size_t dstOffset = MapTileIndicesToGlobalOffset<GlobalData>(row, col, shapes, strides);
109	            if constexpr (atomicType == AtomicType::AtomicAdd) {
110	                dst.AddToElement(dstOffset, val);
111	            } else {
112	                dst.SetElement(dstOffset, val);
113	            }
114	        }
115	    }
116	}
117	
118	template <
119	    typename TileData, typename GlobalData, QuantMode_t quantMode, bool applyRelu,
120	    AtomicType atomicType = AtomicType::AtomicNone>
121	PTO_INTERNAL void TSTORE_IMPL(GlobalData& dst, TileData& src, const std::vector<uint64_t>& scalars = {})
122	{
123	    static_assert(
124	        GlobalData::layout == pto::Layout::ND || GlobalData::layout == pto::Layout::DN ||
125	            GlobalData::layout == pto::Layout::NZ || GlobalData::layout == pto::Layout::NDC1HWC0 ||
126	            GlobalData::layout == pto::Layout::NC1HWC0,
127	        "Only ND, DN, NZ, NC1HWC0 and NDC1HWC0 GLobal Tensors are currently supported");
128	    if constexpr (is_conv_tile_v<TileData>) {
129	        TStoreConv<GlobalData, TileData, atomicType>(dst, src);
130	    } else {
131	        TStore<GlobalData, TileData, quantMode, applyRelu, atomicType>(dst, src, scalars);
132	    }
133	}
