135	template <typename TileData, typename GlobalData, AtomicType atomicType, STPhase Phase = STPhase::Unspecified>
136	PTO_INTERNAL void TSTORE_IMPL(GlobalData& dst, TileData& src)
137	{
138	    (void)Phase;
139	    TSTORE_IMPL<TileData, GlobalData, QuantMode_t::NoQuant, false, atomicType>(dst, src);
140	}
