142	template <
143	    typename TileData, typename GlobalData, AtomicType atomicType, ReluPreMode reluPreMode,
144	    STPhase Phase = STPhase::Unspecified>
145	__aicore__ void TSTORE_IMPL(GlobalData& dst, TileData& src)
146	{
147	    (void)Phase;
148	    constexpr bool useRelu = reluPreMode == ReluPreMode::NormalRelu;
149	    TSTORE_IMPL<TileData, GlobalData, QuantMode_t::NoQuant, useRelu, atomicType>(dst, src);
150	}
151	
152	template <
153	    typename TileData, typename GlobalData, AtomicType atomicType, ReluPreMode reluPreMode,
154	    STPhase Phase = STPhase::Unspecified>
155	__aicore__ void TSTORE_IMPL(GlobalData& dst, TileData& src, uint64_t preQuantScalar)
156	{
157	    (void)Phase;
158	    constexpr QuantMode_t quantPre = GetScalarPreQuantMode<typename TileData::DType, typename GlobalData::DType>();
159	    constexpr bool useRelu = reluPreMode == ReluPreMode::NormalRelu;
160	    size_t vector_size = 0;
161	    if constexpr (TileData::isRowMajor) {
162	        vector_size = src.GetValidCol();
163	    } else {
164	        vector_size = src.GetValidRow();
165	    }
166	    std::vector<uint64_t> scalars(vector_size, preQuantScalar);
167	    TSTORE_IMPL<TileData, GlobalData, quantPre, useRelu, atomicType>(dst, src, scalars);
168	}
