13	
14	#include <unistd.h>
15	#include <vector>
16	
17	namespace pto {
18	
19	template <typename T>
20	constexpr size_t GetC0ElemCount()
21	{
22	    return std::is_same_v<T, int32_t> ? static_cast<size_t>(ACC_C0_SIZE)
23	                                      : static_cast<size_t>(C0_SIZE_BYTE) / sizeof(T);
24	}
25	
26	template <typename T, typename = void>
27	struct HasSFractal : std::false_type {};
28	template <typename T>
29	struct HasSFractal<T, std::void_t<decltype(T::SFractal)>> : std::true_type {};
30	
31	template <typename TileData>
32	using TypeSum = std::conditional_t<
33	    std::is_same_v<typename TileData::DType, half> || std::is_same_v<typename TileData::DType, bfloat16_t>, float,
34	    typename TileData::DType>;
35	
36	template <typename TileData>
37	size_t inline GetTileElementOffsetSubfractals(size_t subTileR, size_t innerR, size_t subTileC, size_t innerC)
38	{
39	    if constexpr (!TileData::isRowMajor & (TileData::SFractal == SLayout::RowMajor)) {
40	        // Nz
41	        return subTileC * TileData::Rows * TileData::InnerCols + subTileR * TileData::InnerNumel +
42	               innerR * TileData::InnerCols + innerC;
43	    } else if constexpr (TileData::isRowMajor & (TileData::SFractal == SLayout::ColMajor)) {
44	        // Zn
45	        return subTileR * TileData::Cols * TileData::InnerRows + subTileC * TileData::InnerNumel +
46	               innerC * TileData::InnerRows + innerR;
47	    } else if constexpr (TileData::isRowMajor & (TileData::SFractal == SLayout::RowMajor)) {
48	        // Zz
49	        return subTileR * TileData::Cols * TileData::InnerRows + subTileC * TileData::InnerNumel +
50	               innerR * TileData::InnerCols + innerC;
51	    } else if constexpr (!TileData::isRowMajor & (TileData::SFractal == SLayout::ColMajor)) {
52	        // Nn
53	        return subTileC * TileData::Rows * TileData::InnerCols + subTileR * TileData::InnerNumel +
54	               innerC * TileData::InnerRows + innerR;
55	    } else {
56	        assert(false && "Invalid layout");
57	    }
58	    return 0;
59	}
60	
61	template <typename TileData>
62	size_t inline GetTileElementOffsetPlain(size_t r, size_t c)
63	{
64	    if constexpr (TileData::isRowMajor) {
65	        return r * TileData::Cols + c;
66	    } else {
67	        return c * TileData::Rows + r;
68	    }
69	}
70	
71	template <typename TileData>
72	size_t inline GetTileElementOffset(size_t r, size_t c)
73	{
74	    if constexpr (TileData::SFractal == SLayout::NoneBox)
75	        return GetTileElementOffsetPlain<TileData>(r, c);
76	    else {
77	        size_t subTileR = r / TileData::InnerRows;
78	        size_t innerR = r % TileData::InnerRows;
79	        return GetTileElementOffsetSubfractals<TileData>(
80	            r / TileData::InnerRows, r % TileData::InnerRows, c / TileData::InnerCols, c % TileData::InnerCols);
81	    }
82	}
83	
84	template <typename ConvTile>
85	size_t inline GetConvTileElementOffset(size_t r, size_t c, const std::vector<int64_t>& shapes)
86	{
87	    const size_t shape0 = static_cast<size_t>(shapes[GlobalTensorDim::DIM_0]);
88	    const size_t shape1 = static_cast<size_t>(shapes[GlobalTensorDim::DIM_1]);
89	    const size_t shape2 = static_cast<size_t>(shapes[GlobalTensorDim::DIM_2]);
90	    const size_t shape3 = static_cast<size_t>(shapes[GlobalTensorDim::DIM_3]);
91	    size_t shape4 = static_cast<size_t>(shapes[GlobalTensorDim::DIM_4]);
92	
93	    constexpr size_t C0 = GetC0ElemCount<typename ConvTile::DType>();
94	    static_assert(C0 != 0, "Divider cannot be equal to zero");
95	
96	    int64_t i0 = 0, i1 = 0, i2 = 0, i3 = 0, i4 = 0, c0 = 0;
97	    if constexpr (ConvTile::layout == pto::Layout::NC1HWC0) {
98	        shape4 = C0;
99	        i3 = r % shape3;
100	        i2 = (r / shape3) % shape2;
101	        i0 = r / (shape2 * shape3);
102	        i4 = c % shape4;
103	        i1 = c / shape4;
104	    } else if constexpr (ConvTile::layout == pto::Layout::NDC1HWC0) {
105	        i4 = r % shape4;
106	        i3 = (r / shape4) % shape3;
107	        i0 = r / (shape3 * shape4);
108	        c0 = c % C0;
109	        i2 = (c / C0) % shape2;
110	        i1 = c / (shape2 * C0);
111	    } else if constexpr (ConvTile::layout == pto::Layout::FRACTAL_Z) {
112	        if constexpr (ConvTile::totalDimCount == 4) {
113	            shape4 = 1;
114	            i2 = c;
115	            i3 = r % shape3;
116	            i1 = (r / shape3) % shape1;
117	            i0 = r / (shape1 * shape3);
118	        } else {
119	            i4 = r % shape4;
120	            i2 = (r / shape4) % shape2;
121	            i1 = (r / (shape2 * shape4)) % shape1;
122	            i0 = r / (shape1 * shape2 * shape4);
123	            i3 = c;
124	        }
125	    }
126	
127	    int64_t offset = i0 * shape1 * shape2 * shape3 * shape4 + i1 * shape2 * shape3 * shape4 + i2 * shape3 * shape4 +
128	                     i3 * shape4 + i4;
129	    if constexpr (ConvTile::layout == pto::Layout::NDC1HWC0) {
130	        offset = offset * C0 + c0;
131	    }
132	    return offset;
133	}
134	
135	template <typename ConvTile>
136	PTO_INTERNAL int64_t CalculateValidRowFromTile(ConvTile& tile)
137	{
138	    if constexpr (ConvTile::layout == pto::Layout::NC1HWC0) {
139	        return tile.GetShape(0) * tile.GetShape(2) * tile.GetShape(3);
140	    } else if constexpr (ConvTile::layout == pto::Layout::NDC1HWC0) {
141	        return tile.GetShape(0) * tile.GetShape(3) * tile.GetShape(4);
142	    } else if constexpr (ConvTile::layout == pto::Layout::FRACTAL_Z) {
143	        if constexpr (ConvTile::totalDimCount == 4) {
144	            return tile.GetShape(0) * tile.GetShape(1) * tile.GetShape(3);
145	        } else {
146	            return tile.GetShape(0) * tile.GetShape(1) * tile.GetShape(2) * tile.GetShape(4);
147	        }
148	    }
149	    return 0;
150	}
151	
152	template <typename ConvTile>
153	PTO_INTERNAL int64_t CalculateValidColFromTile(ConvTile& tile)
154	{
155	    constexpr size_t C0 = GetC0ElemCount<typename ConvTile::DType>();
156	    if constexpr (ConvTile::layout == pto::Layout::NC1HWC0) {
157	        return tile.GetShape(1) * C0;
158	    } else if constexpr (ConvTile::layout == pto::Layout::NDC1HWC0) {
159	        return tile.GetShape(1) * tile.GetShape(2) * C0;
160	    } else if constexpr (ConvTile::layout == pto::Layout::FRACTAL_Z) {
161	        if constexpr (ConvTile::totalDimCount == 4) {
162	            return tile.GetShape(2);
163	        } else {
164	            return tile.GetShape(3);
165	        }
166	    }
167	    return 0;
168	}
169	
170	template <typename GlobalData>
171	size_t inline GetGlobalElementOffsetPlain(GlobalData& gdata, size_t r, size_t c)
172	{
173	    return r * gdata.GetStride(GlobalTensorDim::DIM_3) + c;
174	}
175	
176	template <typename GlobalData>
177	size_t inline MapTileIndicesToGlobalOffset(
178	    size_t r, size_t c, const std::vector<int64_t>& globalShapes, const std::vector<int64_t>& globalStrides)
179	{
180	    const size_t shape0 = static_cast<size_t>(globalShapes[GlobalTensorDim::DIM_0]);
181	    const size_t shape1 = static_cast<size_t>(globalShapes[GlobalTensorDim::DIM_1]);
182	    const size_t shape2 = static_cast<size_t>(globalShapes[GlobalTensorDim::DIM_2]);
183	    const size_t shape3 = static_cast<size_t>(globalShapes[GlobalTensorDim::DIM_3]);
184	    const size_t shape4 = static_cast<size_t>(globalShapes[GlobalTensorDim::DIM_4]);
185	
186	    constexpr size_t C0 = GetC0ElemCount<typename GlobalData::DType>();
187	    static_assert(C0 != 0, "Divider cannot be equal to zero");
188	
189	    int64_t i0, i1, i2, i3, i4, c0 = 0;
190	    if constexpr (GlobalData::layout == pto::Layout::ND) {
191	        i4 = c;
192	        i3 = r % shape3;
193	        i2 = (r / shape3) % shape2;
194	        i1 = (r / (shape3 * shape2)) % shape1;
195	        i0 = r / (shape1 * shape2 * shape3);
196	    } else if constexpr (GlobalData::layout == pto::Layout::DN) {
197	        i3 = r;
198	        i4 = c % shape4;
199	        i2 = (c / shape4) % shape2;
200	        i1 = (c / (shape4 * shape2)) % shape1;
201	        i0 = c / (shape1 * shape2 * shape4);
202	    } else if constexpr (GlobalData::layout == pto::Layout::NZ) {
203	        const size_t outerCol = c / shape4;
204	        i0 = outerCol / shape1;
205	        i1 = outerCol % shape1;
206	        i2 = r / shape3;
207	        i3 = r % shape3;
208	        i4 = c % shape4;
209	    } else if constexpr (GlobalData::layout == pto::Layout::NC1HWC0) {
210	        i3 = r % shape3;
211	        i2 = (r / shape3) % shape2;
212	        i0 = r / (shape2 * shape3);
213	        i4 = c % shape4;
214	        i1 = c / shape4;
215	    } else if (GlobalData::layout == pto::Layout::NDC1HWC0) {
216	        i4 = r % shape4;
217	        i3 = (r / shape4) % shape3;
218	        i0 = r / (shape3 * shape4);
219	        c0 = c % C0;
220	        i2 = (c / C0) % shape2;
221	        i1 = c / (shape2 * C0);
222	    } else if (GlobalData::layout == pto::Layout::FRACTAL_Z) {
223	        i4 = r % shape4;
224	        i2 = (r / shape4) % shape2;
225	        i1 = (r / (shape2 * shape4)) % shape1;
226	        i0 = r / (shape1 * shape2 * shape4);
227	        i3 = c;
228	    } else if constexpr (GlobalData::layout == pto::Layout::MX_A_ZZ) {
229	        i0 = 0;
230	        i1 = r / MX_ROW_LEN;
231	        i2 = c / MX_COL_LEN;
232	        i3 = r % MX_ROW_LEN;
233	        i4 = c % MX_COL_LEN;
234	    } else if constexpr (GlobalData::layout == pto::Layout::MX_B_NN) {
235	        i0 = 0;
236	        i1 = c / MX_ROW_LEN;
237	        i2 = r / MX_COL_LEN;
238	        i3 = c % MX_ROW_LEN;
239	        i4 = r % MX_COL_LEN;
240	    } else if constexpr (GlobalData::layout == pto::Layout::MX_A_ND) {
241	        i0 = 0;
242	        i1 = 0;
243	        i2 = r;
244	        i3 = c / MX_COL_LEN;
245	        i4 = c % MX_COL_LEN;
246	    } else if constexpr (GlobalData::layout == pto::Layout::MX_A_DN) {
247	        i0 = 0;
248	        i1 = 0;
249	        i2 = c / MX_COL_LEN;
250	        i3 = r;
251	        i4 = c % MX_COL_LEN;
252	    } else if constexpr (GlobalData::layout == pto::Layout::MX_B_ND) {
253	        i0 = 0;
254	        i1 = 0;
255	        i2 = r / MX_COL_LEN;
256	        i3 = c;
257	        i4 = r % MX_COL_LEN;
258	    } else if constexpr (GlobalData::layout == pto::Layout::MX_B_DN) {
259	        i0 = 0;
260	        i1 = 0;
261	        i2 = c;
262	        i3 = r / MX_COL_LEN;
263	        i4 = r % MX_COL_LEN;
264	    } else {
265	        throw std::invalid_argument("Unsupported layout in MapTileIndicesToGlobalOffset");
266	    }
267	
268	    const auto offset = i0 * globalStrides[GlobalTensorDim::DIM_0] + i1 * globalStrides[GlobalTensorDim::DIM_1] +
269	                        i2 * globalStrides[GlobalTensorDim::DIM_2] + i3 * globalStrides[GlobalTensorDim::DIM_3] +
270	                        i4 * globalStrides[GlobalTensorDim::DIM_4] + c0;
271	    return static_cast<size_t>(offset);
272	}
273	
274	template <typename DataStorage>
275	size_t inline GetDataElementOffset(DataStorage& storage, size_t r, size_t c)
276	{
277	    if constexpr (HasSFractal<DataStorage>::value) {
278	        return GetTileElementOffset<DataStorage>(r, c);
279	    } else {
280	        return GetGlobalElementOffsetPlain(storage, r, c);
281	    }
282	    return 0;
283	}
284	
285	} // namespace pto
286	#endif
